def choose_move(observation):
    def sget(key, default=None):
        try:
            return observation.get(key, default)
        except Exception:
            return default

    def first_pair(obj, default=None):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def pos_from(keys, default=None):
        for k in keys:
            v = sget(k)
            p = first_pair(v)
            if p is not None:
                return p
        return default

    def step_toward(src, dst):
        if src is None or dst is None:
            return [0, 0]
        sx, sy = src
        tx, ty = dst
        dx = 0 if tx == sx else (1 if tx > sx else -1)
        dy = 0 if ty == sy else (1 if ty > sy else -1)
        return [dx, dy]

    def step_away(src, dst):
        if src is None or dst is None:
            return [0, 0]
        sx, sy = src
        tx, ty = dst
        dx = 0 if tx == sx else (-1 if tx > sx else 1)
        dy = 0 if ty == sy else (-1 if ty > sy else 1)
        return [dx, dy]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_move(m):
        dx, dy = first_pair(m, (0, 0))
        if dx is None:
            dx = 0
        if dy is None:
            dy = 0
        dx = -1 if dx < -1 else (1 if dx > 1 else dx)
        dy = -1 if dy < -1 else (1 if dy > 1 else dy)
        return [dx, dy]

    env = sget("environment_name", "resource_collection")
    self_pos = pos_from(("self_position", "position", "self_pos"), (0, 0))
    opp_pos = pos_from(("opponent_position", "enemy_position", "opponent_pos"), None)
    grid_w = sget("grid_width", 0) or 0
    grid_h = sget("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = sget("self_role", "pursuer")
        if role == "pursuer":
            return clamp_move(step_toward(self_pos, opp_pos))
