        if opp_pos is None:
            return [0, 0]
        target = None
        best = None
        for c in corners:
            d = manhattan(c, opp_pos)
            if best is None or d > best:
                best = d
                target = c
        return clamp_move(step_toward(self_pos, target))

    if env == "territory_control":
        candidates = []
        for k in ("unclaimed_cells", "neutral_cells", "opponent_territory", "targets", "frontier"):
            v = sget(k) or []
            if v:
                candidates = v
                break
