        if opp_pos is not None:
            return clamp_move(step_toward(self_pos, opp_pos))
        return [0, 0]

    resources = sget("resources") or sget("resource_positions") or []
    carrying = sget("carrying", sget("has_resource", False))
    home = pos_from(("home_position", "base_position", "spawn_position", "deposit_position"), None)

    if carrying and home is not None:
        return clamp_move(step_toward(self_pos, home))

    if resources:
